class RunningAverage:
    def __init__(self):
        self._avg = 0.0
        self._count = 0

    def append(self, value: float) -> None:
        if isinstance(value, torch.Tensor):
            value = value.item()
        self._avg = (value + self._count * self._avg) / (self._count + 1)
        self._count += 1

    @property
    def avg(self) -> float:
        return self._avg

    @property
    def count(self) -> int:
        return self._count

    def reset(self) -> None:
        self._avg = 0.0
        self._count = 0


class RunningAverageDict:
    def __init__(self):
        self._dict = None

    def update(self, new_dict):
        if self._dict is None:
            self._dict = dict()
            for key, value in new_dict.items():
                self._dict[key] = RunningAverage()

        for key, value in new_dict.items():
            self._dict[key].append(value)

    def get_value(self) -> Dict[str, float]:
        return {key: value.avg for key, value in self._dict.items()}

    def reset(self) -> None:
        if self._dict is None:
            return
        for k in self._dict.keys():
            self._dict[k].reset()


class Timer:
    def __init__(self):
        self._now = time.process_time()
        # self._now = time.process_time_ns()

    def update(self) -> float:
        current = time.process_time()
        # current = time.process_time_ns()
        duration = current - self._now
        self._now = current
        return duration / 1e6  # ms

